// '구독 신청' 페이지에서 본인 구독 해지가 완료되었을 때 프론트엔드가 호출한다.
// 신규 구독 웰컴 메일(newsletter/welcome)과 대칭되는 해지 안내 메일 전용 웹훅.
const data = $json.body || $json;
function txt(v){ return v===null||v===undefined?'':String(v).trim(); }
function esc(v){
  return txt(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

const email = txt(data.email);
const name = txt(data.name) || '구독자';
if (!email) throw new Error('email이 필요합니다.');

const subject = '[Research On] 뉴스레터 구독이 해지되었습니다';
const goodbyeHtml = `
<div style="font-family:'Malgun Gothic',sans-serif;max-width:600px;margin:0 auto;color:#0f172a">
  <div style="background:linear-gradient(135deg,#475569,#1e293b);padding:28px 32px;border-radius:16px 16px 0 0">
    <div style="color:#ffffff;font-size:13px;font-weight:800;letter-spacing:.08em;opacity:.85">RESEARCH ON</div>
    <div style="color:#ffffff;font-size:22px;font-weight:900;margin-top:6px">뉴스레터 구독이 해지되었습니다</div>
  </div>
  <div style="background:#ffffff;border:1px solid #e5eaf2;border-top:0;border-radius:0 0 16px 16px;padding:28px 32px">
    <p style="font-size:15px;line-height:1.7;margin:0 0 16px">${esc(name)}님, 안녕하세요.</p>
    <p style="font-size:14px;line-height:1.8;color:#334155;margin:0 0 20px">
      요청하신 대로 Research On 뉴스레터 구독이 정상적으로 해지되었습니다.
      더 이상 정기 발송 메일이 발송되지 않습니다.
    </p>
    <div style="background:#f1f5f9;border-radius:12px;padding:16px 18px;margin-bottom:20px">
      <div style="font-size:13px;font-weight:800;color:#334155;margin-bottom:4px">다시 구독하고 싶다면</div>
      <div style="font-size:13.5px;color:#475569;line-height:1.6">Research On 리서치허브의 "구독 신청" 메뉴에서 언제든 다시 신청하실 수 있습니다.</div>
    </div>
    <p style="font-size:13px;color:#697386;line-height:1.7;margin:0">
      그동안 Research On 뉴스레터를 구독해주셔서 감사합니다.
    </p>
    <p style="font-size:13px;color:#94a3b8;margin-top:24px">Research On · BPO사업본부</p>
  </div>
</div>`;

return [{ json: { email, name, subject, goodbye_html: goodbyeHtml } }];

const g = $json;
const ctx = $('G1. Code - 입력 검증 + 해지 안내 메일 본문 구성').first().json;
return [{ json: {
  success: true,
  message: `${ctx.name}님(${ctx.email})에게 구독 해지 안내 메일을 발송했습니다.`,
  email: ctx.email,
  gmail_message_id: g.id || g.messageId || ''
}}];
